#include "exotic/autonomy/agents/in_memory_repository.hpp"
#include "exotic/autonomy/agents/router.hpp"
#include <cassert>
using namespace exotic::autonomy;
using namespace exotic::autonomy::agents;
static AgentId add(AgentRegistry&r,std::string key,double proficiency,double reliability,std::uint32_t active){AgentIdentity a;a.identity_key=key;a.display_name=key;a.status=AgentStatus::Registered;a.health=HealthState::Healthy;a.trust=TrustLevel::Elevated;a.domain_scopes={"software"};a.workload.maximum_tasks=3;a.workload.active_tasks=active;a.workload.utilization=static_cast<double>(active)/3.0;a.cost.fixed_cost_usd=1.0;auto id=r.register_agent(a);r.activate(id);r.grant_capability({id,"software.cpp",proficiency,reliability,0,0,Clock::now()});return id;}
int main(){InMemoryAgentRepository repo;AgentRegistry registry{repo};CapabilityDefinition c;c.key="software.cpp";c.name="C++";registry.define_capability(c);auto busy=add(registry,"busy",0.99,0.99,2);auto balanced=add(registry,"balanced",0.90,0.95,0);AllowAllGovernanceCompatibility gov;AllowAllResourceCompatibility res;CandidateScorer scorer{repo,registry,gov,res};WorkAllocator allocator{repo,scorer};TaskRequirement req;req.job_id=1;req.proposal_id=1;req.domain="software";req.capabilities={{"software.cpp",0.8,0.8,true,1.0}};req.minimum_trust=TrustLevel::Standard;req.maximum_team_cost_usd=5.0;auto decision=allocator.allocate(req);assert(decision.allocated&&decision.assignment);assert(decision.assignment->plan.agent_ids.size()==1);assert(decision.assignment->plan.agent_ids.front()==balanced);assert(decision.assignment->plan.agent_ids.front()!=busy);return 0;}
